import pandas as pd

df_kh = pd.DataFrame({
    "ma_kh": ["K1", "K1"],
    "ten": ["An", "An_VP"]
})
df_don = pd.DataFrame({
    "ma_kh": ["K1", "K1"],
    "tien": [100, 250]
})

df_nhan = pd.merge(df_kh, df_don, on="ma_kh")
print(df_nhan)

import numpy as np
import pandas as pd

df_chinh = pd.DataFrame({
    "gia": [100.0, np.nan, 300.0],
    "kho": ["K1", np.nan, "K2"]
}, index=["P1", "P2", "P3"])

df_phu = pd.DataFrame({
    "gia": [105.0, 200.0, np.nan],
    "kho": ["K1", "K3", "K2"]
}, index=["P1", "P2", "P3"])

df_va = df_chinh.combine_first(df_phu)
print(df_va)
